import { test, expect } from '@playwright/test';

test.describe('Success Feedback on Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display success feedback after valid form submission', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/form-submit', (route) => {
      route.continue();
    });

    // Fill in the form using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('Hello, this is a test message.');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success feedback to appear
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify success feedback is displayed
    await expect(successMessage).toContainText('Form submitted successfully');

    // Verify success icon appears
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();

    // Verify form is cleared
    const nameInputAfter = page.getByLabel('Name');
    await expect(nameInputAfter).toHaveValue('');

    // Verify form is not visible
    const formContainer = page.locator('[data-testid="form-container"]');
    await expect(formContainer).not.toBeVisible();
  });

  test('should display error feedback when form submission fails', async ({ page }) => {
    // Intercept the form submission API with a failure response
    await page.route('**/api/form-submit', (route) => {
      route.abort('failed');
    });

    // Fill in the form using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane.doe@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message with an error.');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error feedback to appear
    const errorMessage = page.getByText('Form submission failed');
    await expect(errorMessage).toBeVisible();

    // Verify error feedback is displayed
    await expect(errorMessage).toContainText('Form submission failed');

    // Verify error icon appears
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify form is still visible
    const formContainer = page.locator('[data-testid="form-container"]');
    await expect(formContainer).toBeVisible();

    // Verify form fields are still filled
    await expect(nameInput).toHaveValue('Jane Doe');
    await expect(emailInput).toHaveValue('jane.doe@example.com');
    await expect(messageInput).toHaveValue('This is a test message with an error.');
  });
});
